import{_ as i,o as u,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const d=JSON.parse('{"title":"Muundo wa Jamii na Uhamiaji wa Tabaka","description":"","frontmatter":{},"headers":[],"relativePath":"sw/0036-社会结构与阶层流动.md","filePath":"sw/0036-社会结构与阶层流动.md"}'),m={name:"sw/0036-社会结构与阶层流动.md"};function w(k,a,o,h,e,l){return u(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="muundo-wa-jamii-na-uhamiaji-wa-tabaka" tabindex="-1">Muundo wa Jamii na Uhamiaji wa Tabaka <a class="header-anchor" href="#muundo-wa-jamii-na-uhamiaji-wa-tabaka" aria-label="Permalink to &quot;Muundo wa Jamii na Uhamiaji wa Tabaka&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>36</td></tr><tr><td>Moduli</td><td>Aina za Utamaduni na Mfumo wa Jamii</td></tr><tr><td>Maneno Muhimu</td><td>Muundo wa Jamii, Uhamiaji wa Tabaka, Mfumo wa Ufunguo, Uinuliwaji wa Haki, Kuzuia Kufungwa</td></tr></tbody></table><h2 id="_1-dhana-za-msingi-za-muundo-wa-jamii-na-matarajio-ya-utamaduni-wa-usawa" tabindex="-1">1. Dhana za Msingi za Muundo wa Jamii na Matarajio ya Utamaduni wa Usawa <a class="header-anchor" href="#_1-dhana-za-msingi-za-muundo-wa-jamii-na-matarajio-ya-utamaduni-wa-usawa" aria-label="Permalink to &quot;1. Dhana za Msingi za Muundo wa Jamii na Matarajio ya Utamaduni wa Usawa&quot;">​</a></h2><p>Muundo wa jamii unamaanisha njia ya shirika na muundo wa uhusiano kati ya vikundi tofauti katika jamii, ikiwa ni pamoja na mwelekeo wa mazingira kama vile mgawanyo wa tabaka, mgawanyo wa majukumu, mgawanyo wa mamlaka, mgawanyo wa rasilimali, n.k. Katika umbo lolote la utamaduni, muundo wa jamii unaathiri sana fursa za maendeleo za mtu binafsi, ufanisi wa utekelezaji wa jamii, na utulivu wa muda mrefu wa utamaduni.</p><p>Katika enzi la mfumo wa uozi wa kula, muundo wa jamii ulionyesha kufungwa kwa kasi na ukosefu wa usawa: kulikuwa na kiota ambacho hakikuweza kuvamiwa kati ya wenye nguvu na walio dhaifu, asili iliamua hatima, na viumbe vya chini vilikuwa na uwezo mdogo sana wa kupanda juu. Muundo huu wa jamii uliofungwa haukusababisha tu mateso yasiyomalizika, bali pia ulisababisha kupoteza uhai wa jamii na kusimama kwa utamaduni — uwezo wa watu wengi mkubwa ulitupiliwa, na watu wachache waliofaidisha, ili kudumisha haki zao za kipekee, hawakujali kukandamiza ubunifu na maendeleo.</p><p>Baada ya utamaduni wa usawa wa neo kuanzishwa, kujenga muundo wa jamii wa &quot;kufunguliwa, kuhamia, kuwa sawa, kuwa na uhai&quot; kuliingizwa kama mojawapo ya malengo ya msingi. Utamaduni wa usawa unaamini kwa dhati: muundo wa jamii wenye afya unapaswa kuruhusu kila mtu binafsi kubadilisha hatima yake kupitia juhudi zake mwenyewe, unapaswa kuruhusu rasilimali za jamii kwenda kwa mtu mwenye uwezo zaidi na mchango mkubwa zaidi, na unapaswa kudumisha njia za kuhamia zinazofaa kati ya tabaka tofauti. Tu kwa njia hii, uwezo wa kuchochea na ubunifu wa viumbe vyote vya usawa vinaweza kuamshwa kikamilifu, na lengo kuu la maendeleo ya pamoja ya kila kabila linaweza实现.</p><p>Matarajio ya msingi ya muundo wa jamii wa utamaduni wa usawa yanaweza kufupishwa katika maneno manne:</p><ol><li><strong>Kufunguliwa na Kujumuisha</strong>: Jamii imefunguliwa kwa kila mtu binafsi, na hauweka vizuizi vya kuingia kwa sababu ya mazingira kama vile kabila, asili, jinsia, n.k.</li><li><strong>Uhamiaji wa Kukamilika</strong>: Njia za kuhamia zinazofaa zimedumishwa kati ya tabaka tofauti, na mtu binafsi anaweza实现 kuhamia juu kupitia juhudi</li><li><strong>Haki na Uadilifu</strong>: Mgawanyo wa rasilimali na utoaji wa fursa unafuata kanuni za haki, na kila mtu binafsi ana fursa sawa za maendeleo</li><li><strong>Kuja na Uhai</strong>: Muundo wa jamii unaweza kuamsha uwezo wa kuchochea na ubunifu wa mtu binafsi, na kudumisha uhai wa kutosha wa maendeleo</li></ol><h2 id="_2-mgawanyo-wa-tabaka-za-jamii-za-utamaduni-wa-usawa" tabindex="-1">2. Mgawanyo wa Tabaka za Jamii za Utamaduni wa Usawa <a class="header-anchor" href="#_2-mgawanyo-wa-tabaka-za-jamii-za-utamaduni-wa-usawa" aria-label="Permalink to &quot;2. Mgawanyo wa Tabaka za Jamii za Utamaduni wa Usawa&quot;">​</a></h2><p>Mgawanyo wa tabaka za jamii za utamaduni wa usawa hauchukui asili, kabila, au utajiri kama vigezo, bali huchukua &quot;kiwango cha usawa&quot; na &quot;kiwango cha uozi&quot; kama rejea ya msingi, na huunda mfumo wa tabaka wenye hamasa na uliofunguliwa:</p><table tabindex="0"><thead><tr><th>Tabaka</th><th>Jina</th><th>Asilimia</th><th>Tabia za msingi</th><th>Majukumu kuu</th></tr></thead><tbody><tr><td>Safu ya kwanza</td><td>Waongozi wa Usawa</td><td>Takriban 1%</td><td>Wenye nguvu wa juu wa位面, kiwango cha usawa cha S, waongozi wa msingi wa utamaduni</td><td>Uamuzi wa mkakati, kudumisha sheria, usimamizi wa kati ya位面</td></tr><tr><td>Safu ya pili</td><td>Mifupa ya Usawa</td><td>Takriban 5%</td><td>Wanafunzi wa uozi wa juu, kiwango cha usawa cha A, nguvu ya mifupa ya kila eneo</td><td>Utafiti na maendeleo ya teknolojia, usimamizi wa shirika, mafunzo ya vipaumbele</td></tr><tr><td>Safu ya tatu</td><td>Wafanyakazi wa Usawa</td><td>Takriban 20%</td><td>Wanafunzi wa uozi wa kati, kiwango cha usawa cha B, vipaumbele vya kitaaluma vya kila tasnia</td><td>Huduma za kitaaluma, matumizi ya teknolojia, usimamizi wa chini</td></tr><tr><td>Safu ya nne</td><td>Watu wa Usawa</td><td>Takriban 60%</td><td>Wanafunzi wa uozi wa mwanzo, kiwango cha usawa cha C, nguvu ya msingi ya utamaduni</td><td>Uozi wa msingi, huduma za uzalishaji, kushiriki katika jumuiya</td></tr><tr><td>Safu ya tano</td><td>Wapya wa Usawa</td><td>Takriban 14%</td><td>Wameingia tu au wanangojea kuboreshwa, kiwango cha usawa cha D, wanahitaji msaada na mwongozo</td><td>Kujifunza na kukua, kupokea mwongozo, kujiunga polepole</td></tr></tbody></table><p>Inahitajika kusisitizwa hasa kwamba, mgawanyo huu wa tabaka haujabaki, bali una hamasa na unaweza kuhamia. Kila mtu binafsi anaweza kuinua kiwango cha usawa na kiwango cha uozi kupitia juhudi zake mwenyewe, na实现 kupanda kwa tabaka; kinyume chake, ikiwa mtu binafsi hana hamasa ya maendeleo au hata anavunja maadili ya usawa, kupungua kwa tabaka kunaweza kutokea.</p><p>Zaidi ya hayo, mgawanyo wa tabaku haumaanishi haki za kipekee na ubaguzi. Watu wa kila tabaka wanafurahia haki za msingi sawa na heshima ya kibinadamu sawa, na tofauti za tabaka zinaonyeshwa hasa katika mgawanyo wa majukumu na mgawanyo wa rasilimali, sio katika juu au chini ya heshima ya kibinadamu.</p><h2 id="_3-mifumo-na-njia-za-uhamiaji-wa-tabaka" tabindex="-1">3. Mifumo na Njia za Uhamiaji wa Tabaka <a class="header-anchor" href="#_3-mifumo-na-njia-za-uhamiaji-wa-tabaka" aria-label="Permalink to &quot;3. Mifumo na Njia za Uhamiaji wa Tabaka&quot;">​</a></h2><p>Utamaduni wa Usawa umeunda mifumo ya uhamiaji wa tabaka yenye njia nyingi na viwango vingi, na kuhakikisha kuwa kila mtu binafsi ana fursa ya实现 kuhamia juu kupitia juhudi zake mwenyewe:</p><h3 id="_3-1-njia-ya-uinuliwaji-wa-uozi" tabindex="-1">3.1 Njia ya Uinuliwaji wa Uozi <a class="header-anchor" href="#_3-1-njia-ya-uinuliwaji-wa-uozi" aria-label="Permalink to &quot;3.1 Njia ya Uinuliwaji wa Uozi&quot;">​</a></h3><p>Uinuliwaji wa uozi ni njia kuu zaidi ya uhamiaji wa tabaka. Utamaduni wa Usawa, kupitia kufunguliwa kwa mifumo mia tatu ya uozi wa asili, hutoa kila mtu binafsi njia ya wazi ya uinuliwaji wa uozi:</p><ul><li><strong>Uinuliwaji wa Kiwango</strong>: Mwanafunzi wa uozi anainua kiwango kupitia uozi, kutoka kwa mwanzo hadi kati, juu, na juu zaidi, na kila mapambano ya kiwango yanaweza kuleta kupanda kwa tabaka</li><li><strong>Mapambano ya Mfumo</strong>: Mwanafunzi wa uozi anapofikia matokeo ya mapambano katika mfumo fulani wa uozi, anaweza获得 kuongezeka kwa kiwango cha usawa na kupanda kwa tabaka</li><li><strong>Ubunifu wa Teknolojia</strong>: Mwanafunzi wa uozi anapofikia matokeo ya ubunifu katika teknolojia ya uozi, teknolojia ya uhandisi, n.k., anaweza获得 heshima na tuzo ya rasilimali, na kuchochea kupanda kwa tabaka</li></ul><p>Kanuni ya msingi ya njia ya uinuliwaji wa uozi ni &quot;kila mtu ana njia&quot; — haijalishi asili ni ipi, kwa muda mrefu anapojitahidi kufanya uozi, kuna fursa ya实现 kupanda kwa tabaka.</p><h3 id="_3-2-njia-ya-uinuliwaji-wa-mchango" tabindex="-1">3.2 Njia ya Uinuliwaji wa Mchango <a class="header-anchor" href="#_3-2-njia-ya-uinuliwaji-wa-mchango" aria-label="Permalink to &quot;3.2 Njia ya Uinuliwaji wa Mchango&quot;">​</a></h3><p>Mbali na kiwango cha uozi, mchango kwa utamaduni wa usawa pia ni msingi muhimu wa uhamiaji wa tabaka:</p><ul><li><strong>Mchango wa Huduma za Umma</strong>: Kushiriki katika huduma za umma kama vile kudumisha neo, mwongozo wa mwalimu, uokoaji wa dharura, n.k., na kukusanya thamani ya mchango</li><li><strong>Mchango wa Utafiti na Maendeleo ya Teknolojia</strong>: Kufanya mchango wa utafiti na maendeleo katika sehemu kama vile teknolojia ya uozi, teknolojia ya uhandisi, n.k.</li><li><strong>Mchango wa Uenezi wa Utamaduni</strong>: Kuenza falsafa ya usawa, kuunda kazi za utamaduni, na kukuza ubadilishaji wa utamaduni</li><li><strong>Mchango wa Kushiriki katika Usimamizi</strong>: Kushiriki katika usimamizi wa jamii, ku Pendekeza sera, na kukuza uboreshaji wa mifumo</li></ul><p>Kanuni ya msingi ya njia ya uinuliwaji wa mchango ni &quot;kazi nyingi faida nyingi&quot; — kadiri mchango kwa utamaduni wa usawa unavyozidi, ndivyo malipo na uinuliwaji wa tabaka unavyozidi.</p><h3 id="_3-3-njia-ya-uinuliwaji-wa-elimu" tabindex="-1">3.3 Njia ya Uinuliwaji wa Elimu <a class="header-anchor" href="#_3-3-njia-ya-uinuliwaji-wa-elimu" aria-label="Permalink to &quot;3.3 Njia ya Uinuliwaji wa Elimu&quot;">​</a></h3><p>Elimu ni ngazi muhimu ya uhamiaji wa tabaka. Utamaduni wa Usawa umeunda mfumo kamili wa uinuliwaji wa elimu:</p><ul><li><strong>Elimu ya Msingi</strong>: Kutoa elimu ya msingi ya uozi bila malipo kwa kila mtu binafsi, na kuhakikisha haki ya kwanza</li><li><strong>Elimu ya Juu</strong>: Kupitia uchunguzi, kuchagua wanafunzi bora kuingia katika chuo cha juu cha uozi, na kupokea mafunzo ya kiwango cha juu zaidi</li><li><strong>Elimu ya Wasomi</strong>: Kuchagua watu binafsi wenye uwezo wa juu zaidi kuingia katika mpango wa mafunzo ya wasomi, na kupokea msaada wa rasilimali ya juu zaidi</li><li><strong>Elimu ya Maisha Yote</strong>: Kutoa fursa za kujifunza na kuboreshwa kwa muda mrefu kwa watu binafsi wa kila umri</li></ul><p>Kanuni ya msingi ya njia ya uinuliwaji wa elimu ni &quot;fursa sawa&quot; — kila mtu binafsi ana fursa sawa ya实现 kupanda kwa tabaka kupitia elimu.</p><h3 id="_3-4-njia-ya-uinuliwaji-wa-maalum" tabindex="-1">3.4 Njia ya Uinuliwaji wa Maalum <a class="header-anchor" href="#_3-4-njia-ya-uinuliwaji-wa-maalum" aria-label="Permalink to &quot;3.4 Njia ya Uinuliwaji wa Maalum&quot;">​</a></h3><p>Kwa watu binafsi wenye mchango wa kipekee au wanaouonyesha vipawa maalum katika sehemu maalum, Utamaduni wa Usawa una njia za uinuliwaji maalum:</p><ul><li><strong>Uinuliwaji wa Kipekee cha Vipawa Maalum</strong>: Kwa mtu binafsi mwenye kipawa maalum au mwenye mchango maalum katika sehemu fulani, anaweza kupandishwa tabaka kwa njia isiyo ya kawaida</li><li><strong>Uinuliwaji kwa Ushindi katika Tukio la Dharura</strong>: Mtu binafsi mwenye ushindi katika kukabiliana na tukio la dharura (kama vile janga, uvamizi, msongo wa mawazo, n.k.) anaweza kupata uinuliwaji wa haraka</li><li><strong>Uinuliwaji kwa Mchango wa Uchunguzi wa Kati ya位面</strong>: Mtu binafsi mwenye mchango wa kipekee katika uchunguzi na uchunguzi wa kale wa kati ya位面 anaweza kupata uinuliwaji</li></ul><h2 id="_4-dhamana-ya-mfumo-ya-kuzuia-kufungwa-kwa-tabaka" tabindex="-1">4. Dhamana ya Mfumo ya Kuzuia Kufungwa kwa Tabaka <a class="header-anchor" href="#_4-dhamana-ya-mfumo-ya-kuzuia-kufungwa-kwa-tabaka" aria-label="Permalink to &quot;4. Dhamana ya Mfumo ya Kuzuia Kufungwa kwa Tabaka&quot;">​</a></h2><p>Ufanisi wa uhamiaji wa tabaka unahitaji dhamana ya mfumo. Utamaduni wa Usawa umeunda mifumo ifuatayo ya kuzuia kufungwa kwa tabaka:</p><h3 id="_4-1-mfumo-wa-kupinga-umiliki" tabindex="-1">4.1 Mfumo wa Kupinga Umiliki <a class="header-anchor" href="#_4-1-mfumo-wa-kupinga-umiliki" aria-label="Permalink to &quot;4.1 Mfumo wa Kupinga Umiliki&quot;">​</a></h3><p>Katiba ya Usawa na Kanuni ya Kupinga Umiliki inakataza kwa uwazi shirika au mtu binafsi yeyote kuumilika rasilimali za uozi, mifumo ya uozi, fursa za elimu, n.k. Mfumo wa kupinga umiliki unazuia vikundi vya manufaa vilivyofika kuvumilia haki zao za kipekee kupitia umiliki wa rasilimali, na kuhakikisha kufunguliwa na kuhamia kwa rasilimali.</p><h3 id="_4-2-mfumo-wa-ushuru-wa-urithi-na-ushuru-wa-zawadi" tabindex="-1">4.2 Mfumo wa Ushuru wa Urithi na Ushuru wa Zawadi <a class="header-anchor" href="#_4-2-mfumo-wa-ushuru-wa-urithi-na-ushuru-wa-zawadi" aria-label="Permalink to &quot;4.2 Mfumo wa Ushuru wa Urithi na Ushuru wa Zawadi&quot;">​</a></h3><p>Ili kuzuia utajiri na rasilimzi kusababisha kufungwa kwa tabaka kupitia uhamishaji wa kizazi, Utamaduni wa Usawa unatekelezwa mfumo wa ushuru wa urithi na ushuru wa zawadi unaozidisha. Urithi na zawadi zenye thamani ya safi ya juu zinahitaji kulipa ushuru wa asili ya juu, na huingizwa kwenye bwawa la rasilimali za umma, na hutumika kwa manufaa ya pamoja ya viumbe vyote vya usawa.</p><h3 id="_4-3-mfumo-wa-haki-ya-elimu" tabindex="-1">4.3 Mfumo wa Haki ya Elimu <a class="header-anchor" href="#_4-3-mfumo-wa-haki-ya-elimu" aria-label="Permalink to &quot;4.3 Mfumo wa Haki ya Elimu&quot;">​</a></h3><p>Utamaduni wa Usawa unahakikisha haki ya elimu kupitia Kanuni ya Dhamana ya Elimu:</p><ul><li>Elimu ya msingi imefunguliwa kwa raia wote bila malipo</li><li>Uchaguzi wa elimu ya juu na elimu ya wasomi unachukua uwezo na uwezo kama vigezo, sio asili na utajiri</li><li>Kutoa msaada wa ziada wa elimu na fidia kwa vikundi dhaifu</li><li>Kukataza kila aina ya ubaguzi wa elimu na haki za kipekee za elimu</li></ul><h3 id="_4-4-mfumo-wa-ufuatiliaji-wa-uhamiaji-wa-tabaka" tabindex="-1">4.4 Mfumo wa Ufuatiliaji wa Uhamiaji wa Tabaka <a class="header-anchor" href="#_4-4-mfumo-wa-ufuatiliaji-wa-uhamiaji-wa-tabaka" aria-label="Permalink to &quot;4.4 Mfumo wa Ufuatiliaji wa Uhamiaji wa Tabaka&quot;">​</a></h3><p>Kiini cha taarifa cha mtandao wa usawa kinafuatilia kwa wakati halisi hali ya uhamiaji wa tabaka za jamii, na viwango vya msingi vya ufuatiliaji vinajumuisha:</p><ul><li><strong>Kiwango cha Uhamiaji wa Kati ya Vizazi</strong>: Kiwango cha tofauti kati ya tabaka ya watoto na tabaka ya wazazi</li><li><strong>Kiwango cha Uhamiaji Juu</strong>: Asilimia ya watu binafsi wanaofikia kupanda kwa tabaka katika kila mzunguko</li><li><strong>Kiwango cha Uhamiaji Chini</strong>: Asilimia ya watu binafsi wanaopitia kupungua kwa tabaka katika kila mzunguko</li><li><strong>Fahirisi ya Kufungwa kwa Tabaka</strong>: Kiwango cha &quot;urithi&quot; ndani ya kila tabaka</li></ul><p>Wakati viwango vya ufuatiliaji vinaonyesha kuwa uhamiaji wa tabaka una hitilafu au mwelekeo wa kufungwa, taasisi za usimamizi zinachukua mara moja marekebisho ya sera, na kuhakikisha ufanisi wa uhamiaji wa tabaka.</p><h2 id="_5-tofauti-za-muundo-wa-jamii-kati-ya-aina-tano-za-utamaduni" tabindex="-1">5. Tofauti za Muundo wa Jamii kati ya Aina Tano za Utamaduni <a class="header-anchor" href="#_5-tofauti-za-muundo-wa-jamii-kati-ya-aina-tano-za-utamaduni" aria-label="Permalink to &quot;5. Tofauti za Muundo wa Jamii kati ya Aina Tano za Utamaduni&quot;">​</a></h2><p>Aina tano za utamaduni wa usawa zina tabia zake za kipekee katika muundo wa jamii:</p><table tabindex="0"><thead><tr><th>Aina</th><th>Tabia za muundo wa jamii</th><th>Tabia za uhamiaji wa tabaka</th></tr></thead><tbody><tr><td>Kuzungumzia Asia ya Mashariki</td><td>Uelekezaji wa jumuiya, daraja wazi, msingi wa familia na madhehebu</td><td>Njia za uhamiaji zinazingatia hasa uinuliwaji wa madhehebu, kasi ya uhamiaji ni wastani</td></tr><tr><td>Maendeleo ya Kaskazini mwa Ulaya</td><td>Ime pangwa kwa usawa, usawa wa juu, tabaka dhaifu</td><td>Tofauti ya tabaka ni ndogo, shinikizo la uhamiaji ni mdogo, kasi ya uhamiaji ni polepole zaidi</td></tr><tr><td>Nyingine za Amerika ya Kaskazini</td><td>Soko, nyingi, ushindani mkali</td><td>Njia za uhamiaji zinazingatia hasa ushindani wa soko, kasi ya uhamiaji ni haraka lakini tofauti ni kubwa</td></tr><tr><td>Jamii ya Barani la Ulaya</td><td>Korporatizimu, uamuzi wa pamoja wa kazi-mali, kidemokrasia cha ushaurishaji</td><td>Njia za uhamiaji zinazingatia hasa sifa za kitaaluma na mazungumzo ya pamoja, uhamiaji ni thabiti</td></tr><tr><td>Maendeleo ya Kufuata</td><td>Serikali yenye nguvu, uhamiaji wa haraka, maendeleo ya gradient</td><td>Kasi ya uhamiaji ni haraka, fursa za kupanda ni nyingi, uhai wa jamii ni wa kutosha</td></tr></tbody></table><p>Ingawa kuna tofauti katika muundo wa jamii wa kila aina, zote zinafuata kanuni za msingi za Katiba ya Usawa, na zote zimejitolea kujenga muundo wa jamii uliofunguliwa, unaohamia, sawa, na wenye uhai.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Muundo wa jamii na uhamiaji wa tabaka ni mojawapo ya mada za msingi za ujenzi wa mifumo ya utamaduni wa usawa wa neo. Utamaduni wa Usawa, kupitia mgawanyo wa tabaka wenye hamasa unaojikita katika kiwango cha usawa na kiwango cha uozi, mifumo ya uhamiaji wa tabaka yenye njia nyingi, na dhamana ya mfumo ya kuzuia kufungwa kwa tabaka, imeunda muundo wa jamii uliofunguliwa, unaohamia, sawa, na wenye uhai. Katika muundo wa jamii kama huu, kila mtu binafsi anaweza kubadilisha hatima yake kupitia juhudi zake mwenyewe, rasilimali za jamii zinaweza kwenda kwa mtu mwenye uwezo zaidi na mchango mkubwa zaidi, na utamaduni mzima unadumisha uhai wa maendeleo wa kutosha. Hii ndiyo msingi muhimu wa jamii unaoruhusu utamaduni wa usawa实现 maendeleo ya pamoja ya kila kabila.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>26-个体与集体平衡原理 (Kanuni ya Usawazishaji kati ya Mtu Binafsi na Kundi)</li><li>29-共生度评估体系 (Mfumo wa Tathmini ya Kiwango cha Usawa)</li><li>30-五种共生文明分型总览 (Muhtasari wa Aina Tano za Utamaduni wa Usawa)</li></ul>',51)])])}const z=i(m,[["render",w]]);export{d as __pageData,z as default};
